<?php
$adminPage='audit';$adminTitle='Audit & reconciliation';$adminPermission='audit.view';require __DIR__.'/../includes/admin_header.php';$ledger=(int)$pdo->query('SELECT COALESCE(SUM(amount_cents),0) FROM ledger_entries')->fetchColumn();$mismatches=(int)$pdo->query('SELECT COUNT(*) FROM accounts a LEFT JOIN (SELECT account_id,SUM(amount_cents) total FROM ledger_entries GROUP BY account_id) l ON l.account_id=a.account_id WHERE a.balance_cents<>COALESCE(l.total,0)')->fetchColumn();$orphans=(int)$pdo->query('SELECT COUNT(*) FROM ledger_entries le LEFT JOIN financial_transactions ft ON ft.transaction_id=le.financial_transaction_id WHERE le.financial_transaction_id IS NOT NULL AND ft.transaction_id IS NULL')->fetchColumn();$logs=$pdo->query('SELECT al.*,u.email actor FROM audit_logs al LEFT JOIN users u ON u.user_id=al.actor_user_id ORDER BY al.created_at DESC LIMIT 150')->fetchAll();$events=$pdo->query('SELECT se.*,u.email FROM security_events se LEFT JOIN users u ON u.user_id=se.user_id ORDER BY se.created_at DESC LIMIT 100')->fetchAll();
?>
<div class="metric-grid"><article class="metric <?=$ledger===0?'reconcile-ok':'reconcile-bad'?>"><span>Global ledger delta</span><strong><?=Money::format($ledger)?></strong></article><article class="metric <?=$mismatches===0?'reconcile-ok':'reconcile-bad'?>"><span>Account mismatches</span><strong><?=$mismatches?></strong></article><article class="metric <?=$orphans===0?'reconcile-ok':'reconcile-bad'?>"><span>Orphan entries</span><strong><?=$orphans?></strong></article><article class="metric"><span>Check time</span><strong style="font-size:1rem"><?=e(gmdate('Y-m-d H:i'))?> UTC</strong></article></div><div class="notice <?=$ledger===0&&$mismatches===0&&$orphans===0?'success':'error'?>"><?=$ledger===0&&$mismatches===0&&$orphans===0?'Ledger and customer-account control totals reconcile.':'Reconciliation exception detected. Stop manual financial operations and investigate.'?></div><div class="app-grid"><section class="panel span-7"><h2>Administrative audit trail</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Target</th></tr></thead><tbody><?php foreach($logs as $row):?><tr><td><?=e(formatDate($row['created_at']))?></td><td><?=e($row['actor']??'System')?></td><td><?=e($row['action'])?></td><td class="mono"><?=e(($row['target_type']??'—').':'.($row['target_id']??'—'))?></td></tr><?php endforeach?></tbody></table></div></section><section class="panel span-5"><h2>Security events</h2><?php foreach($events as $row):?><div class="note"><strong><?=e(str_replace('_',' ',$row['event_type']))?></strong><br><span class="muted"><?=e($row['email']??'Anonymous')?> · <?=e(formatDate($row['created_at']))?> · <?=e($row['ip_address']??'—')?></span></div><?php endforeach;if(!$events):?><div class="empty">No security events.</div><?php endif?></section></div><?php require __DIR__.'/../includes/admin_footer.php';?>
